"use strict";

const fs=require("node:fs");
const path=require("node:path");

const FACTORY_ROOT=path.resolve(__dirname,"..");
const DEFAULT_ENTRIES=[
  "runtime/create-runtime.js",
  "runtime/appdeploy-bridge.js"
];

function normalizeId(file){
  return path.relative(FACTORY_ROOT,file).replaceAll(path.sep,"/");
}

function resolveRelative(fromFile,request){
  const base=path.resolve(path.dirname(fromFile),request);
  const candidates=[
    base,
    base+".js",
    base+".json",
    path.join(base,"index.js"),
    path.join(base,"index.json")
  ];
  for(const candidate of candidates){
    if(fs.existsSync(candidate)&&fs.statSync(candidate).isFile()){
      const rel=path.relative(FACTORY_ROOT,candidate);
      if(rel.startsWith(".."+path.sep)||path.isAbsolute(rel)){
        throw new Error("runtime dependency escapes factory root: "+request);
      }
      return candidate;
    }
  }
  throw new Error("unresolved runtime dependency "+request+" from "+normalizeId(fromFile));
}

function parseRequires(source){
  const out=[];
  const re=/require\(\s*(["'])([^"']+)\1\s*\)/g;
  let match;
  while((match=re.exec(source))!==null){
    out.push({full:match[0],request:match[2],index:match.index});
  }
  return out;
}

function collectRuntimeGraph({entries=DEFAULT_ENTRIES}={}){
  const queue=entries.map(entry=>path.resolve(FACTORY_ROOT,entry));
  const modules=new Map();
  const external=[];

  while(queue.length){
    const file=queue.shift();
    if(modules.has(file))continue;
    if(!fs.existsSync(file))throw new Error("runtime entry missing: "+normalizeId(file));

    const ext=path.extname(file).toLowerCase();
    if(ext===".json"){
      const parsed=JSON.parse(fs.readFileSync(file,"utf8"));
      modules.set(file,{
        id:normalizeId(file),
        source:"module.exports="+JSON.stringify(parsed)+";",
        dependencies:[]
      });
      continue;
    }
    if(ext!==".js")throw new Error("unsupported runtime module type: "+file);

    const source=fs.readFileSync(file,"utf8");
    const deps=[];
    for(const found of parseRequires(source)){
      if(!found.request.startsWith(".")){
        external.push({from:normalizeId(file),request:found.request});
        continue;
      }
      const resolved=resolveRelative(file,found.request);
      deps.push({request:found.request,resolved,id:normalizeId(resolved)});
      queue.push(resolved);
    }
    modules.set(file,{id:normalizeId(file),source,dependencies:deps});
  }

  return {
    entries:entries.map(entry=>entry.replaceAll("\\","/")),
    modules:[...modules.values()].sort((a,b)=>a.id.localeCompare(b.id)),
    external
  };
}

function escapeRegex(value){
  return value.replace(/[\\^$.*+?()[\]{}|]/g,"\\$&");
}

function rewriteRequires(module){
  let source=module.source;
  for(const dep of module.dependencies){
    const re=new RegExp("require\\(\\s*([\"'])"+escapeRegex(dep.request)+"\\1\\s*\\)","g");
    source=source.replace(re,"require("+JSON.stringify(dep.id)+")");
  }
  return source;
}

function buildAppDeployRuntimeBundle({entries=DEFAULT_ENTRIES}={}){
  const graph=collectRuntimeGraph({entries});
  if(graph.external.length){
    throw new Error(
      "AppDeploy ESM bundle has external CommonJS dependencies: "+
      graph.external.map(x=>x.from+" -> "+x.request).join(", ")
    );
  }

  const moduleEntries=graph.modules.map(module=>{
    const body=rewriteRequires(module);
    return JSON.stringify(module.id)+":function(module,exports,require){\n"+body+"\n}";
  });

  const source=[
    "// Generated by scripts/build-appdeploy-runtime-bundle.js",
    "// Self-contained ESM wrapper around the factory CommonJS runtime graph.",
    "const __modules={",
    moduleEntries.join(",\n"),
    "};",
    "const __cache=Object.create(null);",
    "function __require(id){",
    "  if(__cache[id])return __cache[id].exports;",
    "  const factory=__modules[id];",
    "  if(!factory)throw new Error('Bundled module not found: '+id);",
    "  const module={exports:{}};",
    "  __cache[id]=module;",
    "  factory(module,module.exports,__require);",
    "  return module.exports;",
    "}",
    "const __runtime=__require('runtime/create-runtime.js');",
    "const __bridge=__require('runtime/appdeploy-bridge.js');",
    "export const createFactoryRuntime=__runtime.createFactoryRuntime;",
    "export const defaultAdapters=__runtime.defaultAdapters;",
    "export const PREFLIGHT_HEADERS=__runtime.PREFLIGHT_HEADERS;",
    "export const createAppDeployRouteMap=__bridge.createAppDeployRouteMap;",
    "export const STATIC_GET_PATHS=__bridge.STATIC_GET_PATHS;",
    "export const bundledModuleIds="+JSON.stringify(graph.modules.map(m=>m.id))+";",
    ""
  ].join("\n");

  return {
    source,
    moduleCount:graph.modules.length,
    moduleIds:graph.modules.map(m=>m.id),
    entries:graph.entries,
    external:graph.external
  };
}

if(require.main===module){
  const result=buildAppDeployRuntimeBundle();
  const out=process.argv[2];
  if(out){
    fs.mkdirSync(path.dirname(path.resolve(out)),{recursive:true});
    fs.writeFileSync(out,result.source,"utf8");
  }
  console.log(JSON.stringify({
    ok:true,
    output:out?path.resolve(out):null,
    moduleCount:result.moduleCount,
    entries:result.entries,
    external:result.external,
    moduleIds:result.moduleIds
  },null,2));
}

module.exports={
  FACTORY_ROOT,
  DEFAULT_ENTRIES,
  parseRequires,
  collectRuntimeGraph,
  buildAppDeployRuntimeBundle
};
